def f(x):
    if x > 0:        # (1)
        y = 1        # (2)
    else:
        y = 2        # (3)
    while y < 5:     # (4)
        y += 1       # (5)
    return y         # (6)

Kanten: 1-2 1-3 2-4 3-4
        4-5 5-4 4-6     E = 7
Knoten:                 N = 6
M = 7 - 6 + 2 = 3
Entscheidungen: if, while -> 2 + 1 = 3

import ast

code = """
def bewerten(p):
    if p < 0:
        raise ValueError
    if p >= 90:
        return 1
    elif p >= 80:
        return 2
    elif p >= 50:
        return 4
    return 5
"""

ENTSCH = (ast.If, ast.For, ast.While,
          ast.IfExp, ast.ExceptHandler)
baum = ast.parse(code)
n = sum(isinstance(k, ENTSCH)
        for k in ast.walk(baum))
print("Komplexität:", n + 1)
# Komplexität: 5

